Below is a comprehensive example of how you can structure a shopping cart application using React and Redux Toolkit for state management. This example includes a cart reducer, actions to add and remove items, and a simple cart component that displays the items and allows addition and removal of items.

First, ensure you have `react-redux` and `@reduxjs/toolkit` installed:

```bash
npm install @reduxjs/toolkit react-redux
```

### `actions.js` (Cart Actions)

```javascript
// src/ducks/cart/actions.js
import { createSlice } from '@reduxjs/toolkit';

const cartInitialState = {
  items: [],
  totalValue: 0,
};

const cartSlice = createSlice({
  name: 'cart',
  initialState: cartInitialState,
  reducers: {
    addItem(state, action) {
      const existingItemIndex = state.items.findIndex(
        (item) => item.item.id === action.payload.item.id
      );

      if (existingItemIndex!== -1) {
        state.items[existingItemIndex].quantity++;
      } else {
        state.items.push({ item: action.payload.item, quantity: 1 });
      }

      state.totalValue += action.payload.item.price;
    },
    removeItem(state, action) {
      const itemIndex = state.items.findIndex(
        (item) => item.item.id === action.payload.item.id
      );

      if (itemIndex!== -1) {
        const quantity = state.items[itemIndex].quantity;

        state.items.splice(itemIndex, 1);
        state.totalValue -= quantity * action.payload.item.price;
      }
    },
  },
});

export const { addItem, removeItem } = cartSlice.actions;
export default cartSlice.reducer;
```

